INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 1, 'n1-cable', 0, 'lab', 'Соедините два компьютера', 'Два компьютера уже настроены: адреса 192.168.0.1 и 192.168.0.2 в одной подсети. Но между ними нет канала. Нажмите «Кабель», выберите первый узел, затем второй, и проверьте связь командой ping.', '', 'Канал — это ребро графа. Без кабеля узлы не могут обменяться даже одним пакетом.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 1, 'n1-switch', 1, 'lab', 'Коммутатор в центре', 'Четыре компьютера, все в одной подсети 192.168.0.0/24, и один коммутатор. Проложите кабели от каждого компьютера к коммутатору. Напрямую у компьютера всего один порт, а коммутатор соединяет сразу многих. Проверьте, что любой достаёт до любого.', '', 'У коммутатора восемь портов. Каждый компьютер подключается своим кабелем к своему порту.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 1, 'n1-fast-path', 2, 'lab', 'Короткий путь против длинного', 'К серверу ведут два пути: через маршрутизатор «Быстрый» (кабели по 20 км) и через «Медленный» (по 1500 км). Сейчас ПК использует длинный путь — отсюда большая задержка распространения (около 5 мкс на километр). Откройте терминал ПК, посмотрите ping и traceroute, затем переключите шлюз по умолчанию на быстрый маршрутизатор.', '', 'Сначала `ip route` — там строка default. Удалите её: `ip route del default`, затем `ip route add default via 10.0.1.1`. Адрес 10.0.1.1 — это «Быстрый» на стороне ПК.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 1, 'n1-diagnose', 3, 'lab', 'Почему не пингуется', 'ПК 1 не достаёт ни до ПК 2, ни до сервера. Адреса настроены верно, ошибок в адресах нет. Найдите две неисправности на нижних уровнях — физическом и канальном — и устраните их. Подсказка: смотрите, что в терминале показывает `ip link` и все ли кабели на месте.', '', 'Один порт выключен программно (`ip link set eth0 up` на нужном компьютере), а у сервера нет кабеля — добавьте его через «Кабель».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 1, 'n1-two-nets', 4, 'lab', 'Две сети и маршрутизатор', 'ПК А живёт в сети 192.168.1.0/24, ПК Б — в 192.168.2.0/24. Их соединяет маршрутизатор, и он уже настроен. Но компьютеры не знают, куда слать пакеты для чужой сети. Так устроен интернет: сеть сетей. Укажите каждому компьютеру шлюз по умолчанию — адрес маршрутизатора в его сети.', '', 'Команда `ip route add default via <адрес маршрутизатора>`. Для ПК А шлюз 192.168.1.1, для ПК Б — 192.168.2.1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 2, 'n2-l1', 0, 'lab', 'Уровень 1–2: порт коммутатора выключен', 'ПК 1 и ПК 2 подключены к коммутатору, адреса настроены верно. Но ПК 2 недоступен. Запустите ping, посмотрите журнал: кадр доходит до коммутатора и дальше идти некуда. Выберите коммутатор и посмотрите на его порты.', '', 'На карточке коммутатора есть список портов с флажками. Порт, к которому подключён ПК 2, выключен. В терминале коммутатора это `show ports` и `port p2 up`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 2, 'n2-l3', 1, 'lab', 'Уровень 3: неправильная маска', 'Два компьютера в одной сети 192.168.0.0/24 подключены через коммутатор. ПК 1 отправляет запрос, а ответа нет. Загляните в журнал: ПК 2 получает пакет, но отвечать не может — по его настройкам адрес ПК 1 «не в его сети», а шлюза у него нет. Найдите ошибку в настройках ПК 2.', '', 'Маска ПК 2 — /25, это только адреса .0–.127, а сам ПК 2 имеет адрес .200. Поставьте /24. Редактируйте поле маски в карточке и нажмите Enter.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 2, 'n2-l4', 2, 'lab', 'Уровень 4: порт никто не слушает', 'ПК пингует сервер без проблем, но подключиться к порту 80 не может: в ответ приходит RST. Сеть в порядке — дело в транспортном уровне. Запустите на сервере прослушивание порта 80: откройте карточку сервера и добавьте порт либо введите в терминале `nc -l 80`.', '', 'Сервер сам отвечает RST, когда порт закрыт. Как только порт слушает, придёт SYN-ACK.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 2, 'n2-fw', 3, 'lab', 'Уровень 4: файрвол режет порт', 'Сервер слушает порт 80, ping проходит, но подключение к порту 80 «молчит»: ни SYN-ACK, ни RST — пакет пропадает. На маршрутизаторе стоит правило файрвола. Найдите его в журнале (строка «файрвол: DROP») и удалите.', '', 'Выберите маршрутизатор: внизу карточки секция «Файрвол». Правило DROP для tcp порт 80 удаляется крестиком. Пинг при этом работает, потому что ICMP правило не затрагивает.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 2, 'n2-stack', 4, 'lab', 'Три поломки на одном пути', 'ПК должен открыть страницу на сервере через коммутатор и маршрутизатор. На пути три неисправности — по одной на физическом, сетевом и транспортном уровне. Идите снизу вверх: ping, журнал, терминал. Когда и ping, и подключение к порту 80 заработают, упражнение засчитано.', '', 'Физика: порт коммутатора для ПК выключен. Сеть: у ПК не задан шлюз по умолчанию (192.168.1.1). Транспорт: сервер не слушает порт 80.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 3, 'n3-hub', 0, 'lab', 'Хаб подслушивается, коммутатор — нет', 'Три компьютера подключены к хабу. ПК 1 и ПК 2 разговаривают, а ПК 3 видит каждый их кадр: хаб повторяет всё на все порты. Замените хаб коммутатором: удалите три кабеля (выберите кабель на схеме и нажмите «Удалить кабель») и подключите компьютеры к коммутатору. Затем нажмите ▶ у цели про подслушивание и убедитесь, что кадр до ПК 3 не доходит.', '', 'Выберите линию кабеля кликом, затем «Удалить кабель». Новое соединение — режим «Кабель»: нажмите на ПК и на коммутатор. Коммутатор после первого обмена знает, за каким портом ПК 1 и ПК 2.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 3, 'n3-loop', 1, 'lab', 'Уберите петлю', 'Три коммутатора соединены кольцом. Широковещательный кадр (а ARP-запрос именно такой) будет ходить по кольцу вечно — шторм. Нажмите ▶ у цели и посмотрите журнал: коммутатор отмечает, что кадр уже проходил здесь. Разорвите кольцо так, чтобы осталось дерево, но сеть связной. Это то, что автоматически делает протокол STP, блокируя лишний порт.', '', 'Выберите любой кабель между коммутаторами и удалите. Три коммутатора останутся связаны цепочкой — этого достаточно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 3, 'n3-vlan', 2, 'lab', 'Две виртуальные сети на одном коммутаторе', 'Бухгалтерия (ПК 1, ПК 2) и разработка (ПК 3, ПК 4) подключены к одному коммутатору и сейчас видят друг друга. Нужно разделить их на два VLAN: бухгалтерия — VLAN 10, разработка — VLAN 20. Внутри отдела связь должна остаться, между отделами — пропасть. Номер VLAN задаётся в карточке коммутатора для каждого порта.', '', 'На коммутаторе: ПК 1 — порт p1, ПК 2 — p2, ПК 3 — p3, ПК 4 — p4. Поставьте VLAN 10 на p1 и p2, VLAN 20 на p3 и p4. Или в терминале: `port p1 vlan 10`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 3, 'n3-trunk', 3, 'lab', 'Транк между коммутаторами', 'Отделы сидят на двух этажах, у каждого этажа свой коммутатор. Бухгалтерия: ПК 1 (первый этаж) и ПК 3 (второй), разработка: ПК 2 и ПК 4. Настройте VLAN 10 и 20 на портах доступа и превратите порт p8 на каждом коммутаторе в транк, чтобы оба VLAN ходили по одному кабелю с метками. ПК одного отдела должны видеть друг друга через этажи, а чужие отделы — нет.', '', 'Порты доступа: p1 — VLAN 10, p2 — VLAN 20 на обоих коммутаторах. Порт p8 каждого коммутатора — «trunk». Без транка метки не пройдут и ПК 1 не достанет до ПК 3.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 4, 'n4-plan', 0, 'lab', 'Раздайте адреса по плану', 'Маршрутизатор настроен, а у четырёх компьютеров адресов нет. Сеть 192.168.10.0/24 разделена на две. Отдел А: 192.168.10.0/26 (шлюз .1, у ПК А1 адрес .2, у ПК А2 — .3). Отдел Б: 192.168.10.64/27 (шлюз .65, ПК Б1 — .66, ПК Б2 — .67). Задайте каждому ПК адрес, маску и шлюз в его карточке и проверьте связь между отделами.', '', 'Маска /26 — это 255.255.255.192, /27 — 255.255.255.224. В карточке ПК: IP в первом поле, длина маски после «/», шлюз по умолчанию — внизу. Или в терминале: `ip addr add 192.168.10.2/26 dev eth0`, `ip route add default via 192.168.10.1`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 4, 'n4-conflict', 1, 'lab', 'Конфликт адресов', 'ПК 2 и ПК 3 получили один и тот же адрес 192.168.0.20. Пока ПК 1 пингует «двойника», ответы приходят то от одного, то от другого. Запустите ping, посмотрите журнал: ARP-ответы пришли от двух устройств. Смените адрес у одного из компьютеров на свободный (например .30), чтобы у каждого был свой.', '', 'Адрес меняется в карточке ПК (поле IP) или командами `ip addr flush dev eth0` и `ip addr add 192.168.0.30/24 dev eth0`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 4, 'n4-three-errors', 2, 'lab', 'Три ошибки в настройках', 'Три компьютера подключены к одной сети через коммутатор, и ни один не достаёт до сервера за маршрутизатором. У каждого своя ошибка: у кого-то опечатка в шлюзе, у кого-то неверная маска, у кого-то адрес из чужой подсети. Адрес маршрутизатора в этой сети — 192.168.1.1, маска сети /24. Исправьте настройки так, чтобы все три пинговали сервер.', '', 'ПК А: шлюз должен быть адресом маршрутизатора. ПК Б: маска /26 не включает шлюз .1 — нужна /24. ПК В: адрес 192.168.2.x не из этой сети, его нужно поменять на 192.168.1.x.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 4, 'n4-nat', 3, 'lab', 'Выход в интернет через NAT', 'Домашняя сеть 192.168.0.0/24 с частными адресами и шлюзом, у которого со стороны провайдера публичный адрес 203.0.113.2. Провайдер (его настроить нельзя) не пропускает частные адреса, поэтому запросы ПК до сайта 198.51.100.10 пропадают. Включите на шлюзе подмену адреса (MASQUERADE на интерфейсе, смотрящем в интернет) и убедитесь, что сайт видит адрес шлюза.', '', 'Выберите шлюз, в секции «NAT» укажите интерфейс eth1 и нажмите «включить». Или в терминале: `iptables -t nat -A POSTROUTING -o eth1 -j MASQUERADE`. Затем нажмите ▶ у цели и посмотрите, как меняется адрес отправителя в журнале.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 4, 'n4-dnat', 4, 'lab', 'Проброс порта внутрь сети', 'Во внутренней сети работает веб-сервер 192.168.0.10, порт 80. MASQUERADE уже включён, поэтому изнутри всё работает. Но гость из интернета (198.51.100.50) не может открыть сайт: снаружи виден только публичный адрес шлюза 203.0.113.2. Пробросьте порт 8080 шлюза на 192.168.0.10:80, чтобы гость мог открыть http://203.0.113.2:8080.', '', 'На шлюзе в секции «NAT» заполните «Проброс порта»: вход eth1, порт 8080, на 192.168.0.10:80. Или в терминале: `iptables -t nat -A PREROUTING -i eth1 -p tcp --dport 8080 -j DNAT --to-destination 192.168.0.10:80`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 5, 'n5-static', 0, 'lab', 'Два маршрутизатора: статические маршруты', 'ПК А живёт в сети 10.1.0.0/24, ПК Б — в 10.2.0.0/24, между ними два маршрутизатора со связующей сетью 10.0.12.0/24. Компьютеры знают свои шлюзы, но маршрутизаторы знают только свои подключённые сети. Добавьте на каждом из них маршрут в «чужую» сеть через соседа, чтобы ПК пинговали друг друга.', '', 'На R1: `ip route add 10.2.0.0/24 via 10.0.12.2`. На R2: `ip route add 10.1.0.0/24 via 10.0.12.1`. Или форма «+ маршрут» в таблице маршрутов маршрутизатора.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 5, 'n5-default', 1, 'lab', 'Маршрут по умолчанию к провайдеру', 'Офисный маршрутизатор подключён к провайдеру, а интернет — это сотни тысяч сетей: перечислять их в таблице невозможно. Добавьте на офисном маршрутизаторе один маршрут по умолчанию через адрес провайдера 203.0.113.1, и ПК откроет сайт 198.51.100.10. (Провайдер уже знает дорогу к вашей сети 192.0.2.0/24 и недоступен для настройки.)', '', 'На маршрутизаторе: `ip route add default via 203.0.113.1`. Затем нажмите ▶ у цели и посмотрите, на каком шаге пакет сворачивает к провайдеру.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 5, 'n5-loop', 2, 'lab', 'Петля маршрутов и TTL', 'ПК пингует сайт, а в ответ — «время жизни истекло». Запустите traceroute до 198.51.100.10 в терминале ПК: адреса R1 и R2 повторяются снова и снова. Маршрутизаторы отправляют пакет друг другу, и только TTL останавливает его. Найдите, чей маршрут по умолчанию указывает не туда, и исправьте так, чтобы R2 отправлял пакет к провайдеру (203.0.113.1).', '', 'На R2 посмотрите `ip route`: default смотрит на R1 (10.9.0.1) — в обратную сторону. Удалите её и добавьте: `ip route del default`, `ip route add default via 203.0.113.1`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 5, 'n5-lpm', 3, 'lab', 'Самый длинный префикс', 'Центральный маршрутизатор знает про всё 10.0.0.0/8 один маршрут — через медленный канал к «Дальнему» (1500 км). Но сервер 1 с адресом 10.1.2.10 на самом деле стоит рядом, за «Ближним» (10 км), и сейчас недоступен. Добавьте более точный маршрут 10.1.2.0/24 через «Ближний»: он выиграет у /8. Маршрут /8 удалять нельзя — за «Дальним» живёт сервер 2 (10.9.9.10).', '', 'На центральном маршрутизаторе: `ip route add 10.1.2.0/24 via 172.16.1.2` — это адрес «Ближнего» на стороне центра. Длинный префикс /24 побеждает /8.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 5, 'n5-return', 4, 'lab', 'Запрос дошёл, ответ потерян', 'ПК не получает ответа от сервера. Запустите traceroute: два шага отвечают, а на третьем (сервер) — звёздочки. Но запрос до сервера доходит! Посмотрите журнал ▶: ответ сервера доходит до R2 и там пропадает. Найдите, чего не хватает в таблице маршрутов R2, и исправьте.', '', 'У R2 нет пути в сеть ПК 10.1.0.0/24. Добавьте: `ip route add 10.1.0.0/24 via 10.0.12.1`. Маршрут нужен в обе стороны.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 6, 'n6-listen', 0, 'lab', 'Сервер не слушает UDP-порт', 'Клиент отправляет датаграммы на порт 5000 сервера, но ничего не получает. В терминале клиента выполните `nc -u 192.168.0.20 5000` и посмотрите на ответ: приходит ICMP «порт недоступен». Запустите на сервере прослушивание UDP-порта 5000 и повторите.', '', 'На сервере в терминале: `nc -u -l 5000`. Или в карточке сервера «Слушающие порты»: протокол udp, порт 5000. TCP-порт с тем же номером — это другой сокет, он не поможет.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 6, 'n6-two', 1, 'lab', 'TCP и UDP на одном сервере', 'Сервер должен отвечать на веб-запросы (TCP, порт 80) и на запросы имён (UDP, порт 53). Сейчас он ничего не слушает. Откройте оба порта и проверьте каждый: TCP-порт 53 при этом должен остаться закрытым — разные протоколы дают разные сокеты.', '', 'В карточке сервера секция «Слушающие порты»: выберите протокол tcp, порт 80; затем udp, порт 53. Терминал: `nc -l 80` и `nc -u -l 53`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 6, 'n6-fw', 2, 'lab', 'Файрвол: только DNS и веб', 'Домашний шлюз по умолчанию запрещает всё (политика DROP на FORWARD). NAT уже настроен. Откройте для клиентов сети то, что нужно: запросы DNS (udp/53) и веб (tcp/80), а также разрешите ответы на уже установленные соединения. SSH (tcp/22) должен остаться закрытым.', '', 'Правила FORWARD по порядку: 1) `-m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT` (ответы), 2) `-p udp --dport 53 -j ACCEPT`, 3) `-p tcp --dport 80 -j ACCEPT`. В форме файрвола выберите состояние «уже установлено» для первого правила.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 6, 'n6-diagnose', 3, 'lab', 'Отказ или молчание', 'Два сервера должны отвечать по UDP на порту 5000. Клиент пробует оба. С первым ответ приходит сразу в виде ICMP «порт недоступен» (отказ), со вторым — тишина (пакеты пропадают). Это две разные причины: у первого порт просто не слушает, а у второго что-то режет пакеты по дороге. Исправьте обе.', '', 'Первый: на сервере 1 откройте UDP-порт 5000 (`nc -u -l 5000`). Второй: на маршрутизаторе в журнале «файрвол: DROP» — удалите правило, режущее UDP на порт 5000.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 7, 'n7-triage', 0, 'lab', 'Три сервера: отказ, молчание, успех', 'Клиент пробует подключиться к порту 80 трёх серверов. Сервер 1 отвечает RST (отказ), сервер 2 молчит, сервер 3 работает. Нажмите ▶ у каждой цели и сравните журналы: RST — узел жив, порт закрыт; тишина — пакет пропал по дороге. Исправьте оба сервера: на первом запустите сервис, а второй освободите от правила файрвола.', '', 'Сервер 1: `nc -l 80` в его терминале. Сервер 2: на маршрутизаторе найдите правило DROP для tcp порт 80 к 10.0.2.10 в секции «Файрвол» и удалите его.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 7, 'n7-sport', 1, 'lab', 'Рукопожатие обрывается на втором шаге', 'Клиент не может подключиться к веб-серверу: ни отказа, ни ответа. Нажмите ▶ у цели и посмотрите журнал: SYN доходит до сервера, сервер отвечает SYN-ACK, но ответ пропадает в маршрутизаторе — кто-то запретил пересылку пакетов с порта 80. Найдите и удалите это правило.', '', 'На маршрутизаторе в секции «Файрвол» есть правило DROP tcp, в логе оно выглядит как «файрвол: DROP». Нужно удалить правило, режущее порт отправителя 80.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 7, 'n7-stateful', 2, 'lab', 'Файрвол с отслеживанием соединений', 'В локальной сети 192.0.2.0/24 живут клиент и свой веб-сервер (порт 80). Снаружи ходят гости. Нужно: клиент ходит в интернет свободно, гость снаружи свободно открывает только то, что нужно, — но к веб-серверу в локальной сети подключаться не должен, хотя ответы на соединения клиента принимаются. Выставьте политику FORWARD DROP, разрешите «уже установленные» соединения и новые соединения из своей сети.', '', 'Правила по порядку: `iptables -P FORWARD DROP`, `iptables -A FORWARD -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT`, `iptables -A FORWARD -s 192.0.2.0/24 -j ACCEPT`. Новое соединение извне (SYN гостя) не попадёт ни под одно разрешение — политика DROP его отбросит.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 8, 'n8-window', 0, 'lab', 'Окно приёма не даёт заполнить канал', 'Сервер отдаёт файл клиенту по каналу 200 Мбит/с с большой задержкой (RTT около 80 мс). Запустите на сервере `iperf3 10.1.0.10` — скорость около 6 Мбит/с, хотя канал в тридцать раз быстрее: окно приёма клиента всего 64 КБ. Увеличьте окно приёма у клиента (получателя), чтобы скорость превысила 150 Мбит/с. Ёмкость канала (BDP) на графике — линия янтарного цвета.', '', 'Нужно окно не меньше BDP ≈ 2 МБ. На клиенте: в карточке — «Окно приёма, КБ» (поставьте 4096) или в терминале `sysctl -w net.ipv4.tcp_rmem="4096 131072 4194304"`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 8, 'n8-cc', 1, 'lab', 'Потери на радиоканале и алгоритм', 'Сервер отправляет данные клиенту через спутниковый канал: 100 Мбит/с, RTT около 100 мс и случайные потери 0,5% пакетов. Классический алгоритм после каждой потери сжимает окно, и скорость падает до единиц Мбит/с. Окно приёма уже достаточно большое. Смените алгоритм управления перегрузкой на сервере (отправителе) на тот, что не считает любую потерю перегрузкой.', '', 'На сервере: в карточке «Алгоритм» — bbr или `sysctl -w net.ipv4.tcp_congestion_control=bbr`. Сначала запустите `iperf3 10.1.0.10`, потом смените алгоритм и повторите — график покажет разницу.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 8, 'n8-bufferbloat', 2, 'lab', 'Раздутие буферов', 'Клиент скачивает файл через домашний маршрутизатор с узким исходящим каналом 20 Мбит/с. Скорость отличная, но при загрузке пинг и звонки «плывут»: очередь на узком месте — 1000 пакетов, и каждый ждёт в ней сотни миллисекунд. Уменьшите очередь на интерфейсе маршрутизатора, смотрящем в узкий канал, так, чтобы RTT под нагрузкой был не больше 80 мс, а скорость не падала ниже 17 Мбит/с.', '', 'Очередь задаётся на интерфейсе, который отправляет в узкий канал (eth1 маршрутизатора): в его карточке поле «очередь» либо `ip link set eth1 txqueuelen 30`. Слишком короткая очередь тоже плоха — канал перестанет заполняться.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-fetch', 0, 'stdout', 'Клиент: отправить запрос и прочитать ответ до конца', 'Напишите функцию fetch(host, port, request): подключитесь по TCP, отправьте все байты request (sendall), затем читайте ответ, пока recv не вернёт пустые байты (собеседник закрыл соединение), и верните весь ответ одним bytes.', 'import socket
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-recv-exact', 1, 'stdout', 'Прочитать ровно n байт', 'recv может вернуть меньше, чем просили. Напишите функцию recv_exact(sock, n): читает из сокета ровно n байт (в цикле) и возвращает их. Если соединение закрылось раньше, чем пришло n байт, поднимите ConnectionError.', 'def recv_exact(sock, n):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-framing', 2, 'stdout', 'Сообщения с длиной впереди', 'TCP — поток байтов, границ сообщений в нём нет. Реализуйте простой протокол: перед каждым сообщением идёт его длина в 4 байтах (big-endian). Напишите send_msg(sock, data: bytes) и recv_msg(sock) -> bytes. Пустое сообщение допустимо; при закрытии соединения вместо длины recv_msg возвращает None.', 'import struct
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-linereader', 3, 'stdout', 'Читатель строк по потоку', 'Данные приходят кусками произвольного размера. Напишите класс LineReader(sock) с методом readline(): возвращает следующую строку (bytes) без завершающего b''\n''; остаток, прочитанный сверх строки, хранится для следующего вызова. Когда соединение закрыто и данных нет — None.', 'class LineReader:
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-echo-once', 4, 'stdout', 'Эхо-сервер для одного клиента', 'Напишите функцию echo_once(listener): слушающий сокет уже создан. Примите одно соединение (accept) и возвращайте клиенту всё, что он присылает, пока он не закроет соединение; закройте сокет клиента. Верните число байтов, которые вы переслали.', 'def echo_once(listener):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-udp-server', 5, 'stdout', 'UDP-сервер: ответ заглавными', 'Напишите функцию udp_upper_server(sock, count): сокет уже привязан к порту. Примите count датаграмм (recvfrom) и на каждую ответьте отправителю (sendto) тем же текстом заглавными буквами (bytes.upper()).', 'def udp_upper_server(sock, count):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-udp-retry', 6, 'stdout', 'UDP-клиент с повторами', 'UDP не повторяет потерянные датаграммы — это делает приложение. Напишите функцию udp_ask(addr, data, timeout=0.2, retries=5): отправьте data на addr и ждите ответ не дольше timeout секунд (settimeout). Не дождались — отправьте снова, всего не больше retries попыток. Верните кортеж (ответ, номер_попытки). Если ни одной не хватило — поднимите TimeoutError.', 'import socket
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-scan', 7, 'stdout', 'Сканер открытых портов', 'Напишите функцию open_ports(host, ports): для каждого порта попробуйте подключиться по TCP (create_connection с таймаутом 0.5 с) и верните отсортированный список портов, на которых подключение удалось. Ошибки подключения (отказ, таймаут) означают «закрыт».', 'import socket
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-threaded', 8, 'stdout', 'Сервер: поток на каждого клиента', 'Напишите функцию threaded_echo(listener, clients): примите clients соединений (accept), для каждого запустите отдельный поток, который возвращает клиенту то, что получает, пока тот не закроет соединение. Дождитесь завершения всех потоков и верните общее число пересланных байтов. Клиенты подключаются одновременно и ждут друг друга, поэтому по очереди обслужить их не получится.', 'import threading
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-selectors', 9, 'stdout', 'Сервер на select: один поток — много клиентов', 'Реализуйте то же, но в одном потоке: select_echo(listener, clients) принимает clients соединений и обслуживает их с помощью модуля selectors (DefaultSelector): новое соединение — регистрируете, пришли данные — возвращаете их клиенту, пустой recv — закрываете и снимаете с регистрации. Когда все клиенты обслужены и закрыты, верните число пересланных байтов. Создавать потоки внутри функции нельзя.', 'import selectors
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-asyncio', 10, 'stdout', 'Асинхронный эхо-обработчик', 'Напишите корутину handle(reader, writer) для asyncio.start_server: читайте строки (reader.readline()) и отправляйте каждую обратно с префиксом b''echo: '' (writer.write + await writer.drain()), пока клиент не закроет соединение (пустая строка). В конце закройте writer (close и await wait_closed()).', 'async def handle(reader, writer):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 9, 'net9-http-get', 11, 'stdout', 'Свой мини-клиент HTTP', 'Напишите функцию http_get(host, port, path): отправьте по сырому сокету запрос ''GET <path> HTTP/1.1'' с заголовками Host и Connection: close, прочитайте ответ до закрытия и разберите его. Верните кортеж (код_статуса: int, заголовки: dict с именами в нижнем регистре, тело: bytes). Заголовки от тела отделяет пустая строка \r\n\r\n.', 'import socket
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 10, 'n10-resolver', 0, 'lab', 'У клиента нет DNS-сервера', 'ПК открывает сайт по адресу, но не по имени: ping www.example.org отвечает «Temporary failure in name resolution». В локальной сети есть рекурсивный резолвер 192.168.0.53. Укажите его на ПК и убедитесь, что имя разрешается и сайт открывается по имени. Нажмите ▶ у цели и посмотрите путь запроса: резолвер идёт к корню, затем к серверу .org, затем к авторитативному серверу.', '', 'На ПК: в карточке поле «DNS-сервер», или `echo "nameserver 192.168.0.53" > /etc/resolv.conf`. Проверка: `dig www.example.org` и `cat /etc/resolv.conf`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 10, 'n10-record', 1, 'lab', 'Запись указывает на старый сервер', 'Сайт переехал на сервер 198.51.100.40, а в зоне example.org запись www всё ещё ведёт на старый адрес 198.51.100.99, где ничего нет. Вы администратор зоны: зайдите на авторитативный сервер, удалите старую запись и добавьте верную. Проверьте, что имя разрешается и порт 80 по имени открывается.', '', 'На авторитативном сервере: в секции DNS-записей удалите запись крестиком и добавьте новую, либо `dns del www.example.org A`, затем `dns add www.example.org A 198.51.100.40`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 10, 'n10-cname', 2, 'lab', 'Псевдоним CNAME', 'У сайта должно быть второе имя shop.example.org, которое ведёт туда же, куда www. Добавьте на авторитативном сервере запись CNAME, а не второй A: тогда при смене адреса менять придётся одну запись. Проверьте, что резолвер возвращает адрес сайта и порт 80 по новому имени открывается.', '', '`dns add shop.example.org CNAME www.example.org` или форма «+ запись»: имя shop.example.org, тип CNAME, значение www.example.org. Резолвер сам доберётся до A.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 10, 'n10-delegation', 3, 'lab', 'Разорвано делегирование', 'Сервер верхнего домена .org «забыл», что зона example.org делегирована авторитативному серверу 198.51.100.30, поэтому на запрос www.example.org отвечает NXDOMAIN. Нажмите ▶ у цели и найдите шаг, где цепочка обрывается. Вы управляете сервером .org: восстановите делегирование.', '', 'На сервере .org: `dns delegate example.org 198.51.100.30` или форма «+ делегирование» (зона example.org, сервер 198.51.100.30).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 10, 'n10-roothint', 4, 'lab', 'Резолвер не знает корня', 'ПК настроен верно, но на любой запрос резолвер возвращает SERVFAIL: в его настройках стоит неверный адрес корневого сервера 198.51.100.99. Найдите причину по журналу ▶ (резолвер не получает ответа), а затем задайте правильный корневой сервер 198.51.100.10.', '', 'На резолвере: `dns root 198.51.100.10` или поле «корневой сервер» в секции DNS. Проверьте `dig www.example.org` на ПК.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 10, 'n10-hosts', 5, 'lab', 'Файл hosts для проверки', 'Перед запуском нового сайта нужно проверить его по имени staging.example.org на тестовом сервере 198.51.100.40, но в DNS такой записи ещё нет (запрос даёт NXDOMAIN). Не трогая DNS, добавьте локальную подсказку в файл hosts на ПК и убедитесь, что пинг и подключение по имени работают.', '', 'На ПК: `echo "198.51.100.40 staging.example.org" >> /etc/hosts`; `cat /etc/hosts` покажет файл. Запись hosts побеждает ответ DNS — так бывает и в жизни, когда «сайт не обновляется» у одного человека.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 11, 'n11-404', 0, 'lab', 'Страница не найдена', 'Ссылка «О нас» ведёт на /about, но сервер отвечает 404 Not Found. Откройте терминал браузера (ПК) и выполните `curl -v http://www.example.org/about`: в стартовой строке ответа виден код. Добавьте на веб-сервере маршрут /about с кодом 200 и текстом, содержащим слово «About».', '', 'На сервере: `web route /about 200 About us page` или форма «+ маршрут» (путь /about, код 200, текст). Затем снова curl.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 11, 'n11-redirect', 1, 'lab', 'Постоянный редирект', 'Страница /old-page переехала на /new-page, но по старому адресу сейчас 404, и поисковики теряют ссылки. Настройте на сервере постоянное перенаправление 301 со старого адреса на новый. Проверьте двумя способами: `curl -I` показывает 301 и заголовок Location, а `curl -L` доходит до итоговой страницы.', '', '`web redirect /old-page 301 /new-page` или форма с кодом 301 и адресом назначения в последнем поле.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 11, 'n11-cache', 2, 'lab', 'Кэш: статика надолго, личное — никогда', 'Сайт отдаёт логотип /logo.png и страницу личного кабинета /account без заголовков кэширования. Логотип браузер каждый раз скачивает заново, а страницу кабинета может сохранить общий кэш. Добавьте заголовки: логотипу — Cache-Control: max-age=31536000 (год), личной странице — Cache-Control: no-store.', '', '`web header /logo.png Cache-Control max-age=31536000` и `web header /account Cache-Control no-store`. Проверка: `curl -I http://www.example.org/logo.png`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 11, 'n11-cookie', 3, 'lab', 'Безопасная cookie сессии', 'После входа на /login сервер выдаёт cookie сессии заголовком Set-Cookie: sid=9f3a без флагов, и любой скрипт на странице её прочитает, а по обычному HTTP она уйдёт открытым текстом. Исправьте заголовок так, чтобы в нём были HttpOnly, Secure и SameSite=Lax.', '', '`web header /login Set-Cookie sid=9f3a; HttpOnly; Secure; SameSite=Lax` — тот же заголовок заменит прежний.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 11, 'n11-etag', 4, 'lab', 'Условный запрос и 304', 'Большой справочник /data меняется редко. Клиент, у которого уже есть копия, должен получать короткий ответ 304 Not Modified вместо повторной загрузки. Задайте ресурсу ETag "v42" и проверьте: `curl -H "If-None-Match: \"v42\"" -v http://www.example.org/data`.', '', '`web etag /data "v42"` (кавычки — часть значения). Запрос с If-None-Match, равным ETag, получит 304 без тела.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 12, 'n12-h2', 0, 'lab', 'Много файлов и большая задержка', 'Страница из 41 файла загружается с далёкого сервера (RTT около 120 мс) по HTTP/1.1: браузер получает ресурсы по шесть штук, и каждая «волна» стоит целого круга. Выполните на ПК `pageload https://www.example.org/` — в таблице видно, сколько заняла бы загрузка по каждой версии. Включите на сервере протокол, который отдаёт все ресурсы одним соединением параллельно, и уложите загрузку в 1,3 секунды.', '', 'На сервере: переключатель «протокол» в карточке — HTTP/2, или `web protocol h2`. HTTP/3 здесь не нужен: потерь на канале нет.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 12, 'n12-h3', 1, 'lab', 'Мобильная сеть с потерями: нужен HTTP/3', 'Клиенты ходят по мобильной сети: RTT около 120 мс и потери 2%. На потерях HTTP/2 страдает от блокировки на TCP, и загрузка занимает несколько секунд. Переведите сайт на HTTP/3, но помните: он живёт на UDP/443. Нажмите «Проверить» и посмотрите на причину: сервер должен слушать udp/443, а файрвол маршрутизатора не должен резать этот порт. Цель — загрузка не дольше 2 с.', '', 'Три шага: 1) `web protocol h3`; 2) на сервере слушать UDP: `nc -u -l 443` или форма «Слушающие порты» (udp, 443); 3) на маршрутизаторе удалить правило, режущее UDP/443. Проверка: `pageload https://www.example.org/` (там же видно откат на HTTP/2).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 12, 'n12-choose', 2, 'lab', 'Новее — не значит лучше', 'Два сайта в разных условиях. Первый (`www.example.org`) далеко, потерь нет. Второй (`app.example.org`) — по ненадёжному каналу с потерями 2%, а корпоративная политика полностью запрещает UDP, так что HTTP/3 недоступен. Выберите на каждом сервере тот протокол, при котором страница грузится быстрее: первый должен укладываться в 1,6 с, второй — в 2,5 с.', '', 'Первый: HTTP/2 — потерь нет, мультиплексирование выигрывает. Второй: из доступных HTTP/1.1 и HTTP/2 при потерях лучше HTTP/1.1: шесть соединений не блокируют друг друга. Сравните таблицы `pageload`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 13, 'n13-expired', 0, 'lab', 'Сертификат просрочен', 'Сайт перестал открываться по HTTPS: `curl https://www.example.org/` выдаёт «certificate has expired». Проверьте срок на сервере (`tls show`; сегодня 2026-10-16) и выпустите новый сертификат на 90 дней у промежуточного центра PublicIntCA на то же имя.', '', 'На сервере: `tls cert new www.example.org --issuer PublicIntCA --days 90`. Цепочка и версии остаются. Проверка: `openssl s_client -connect www.example.org:443`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 13, 'n13-name', 1, 'lab', 'Имя не совпадает с сертификатом', 'Сертификат выпущен только на example.org, а пользователи открывают www.example.org. Браузер отказывает: имя не найдено среди SAN. Выпустите сертификат, в котором есть оба имени: example.org и www.example.org.', '', '`tls cert new example.org www.example.org --issuer PublicIntCA --days 90` — первое имя становится CN, все перечисленные попадают в SAN.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 13, 'n13-chain', 2, 'lab', 'Забытый промежуточный сертификат', 'У вас сайт открывается, у клиентов — «unable to get local issuer certificate». Сервер присылает только листовой сертификат, а выдавший его PublicIntCA клиент не знает: в хранилище доверия только корневой PublicRootCA. Добавьте промежуточный сертификат в цепочку, которую присылает сервер.', '', '`tls chain add PublicIntCA`. Сервер должен присылать листовой и все промежуточные сертификаты; корневой клиент уже знает.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 13, 'n13-trust', 3, 'lab', 'Внутренний центр сертификации', 'Внутренний сервис intranet.corp использует сертификат от корпоративного центра CorpIntCA (его корень — CorpRootCA). Он правильно настроен на сервере: срок, имя и цепочка в порядке. Но корень CorpRootCA нет в хранилище доверия ПК, поэтому браузер ругается на «self-signed certificate in chain». Добавьте CorpRootCA в доверенные на ПК — так делают на корпоративных устройствах. Осторожно: лишний корень в хранилище — дыра в безопасности.', '', 'На ПК: `trust show`, затем `trust add CorpRootCA`. Проверка: `curl https://intranet.corp/`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 13, 'n13-version', 4, 'lab', 'Старая версия TLS', 'Сервер настроен давно и поддерживает только TLS 1.0 и 1.1: современные клиенты их отключили и получают alert protocol version. Включите на сервере TLS 1.2 и 1.3. Затем выполните `openssl s_client -connect www.example.org:443` и посмотрите, сколько кругов занимает рукопожатие.', '', '`tls versions 1.2,1.3` — клиент выберет самую новую из общих: 1.3, рукопожатие за один круг.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-rest-get', 0, 'stdout', 'REST: чтение ресурсов', 'Напишите класс Handler (наследник BaseHTTPRequestHandler) с методом do_GET. Словарь ITEMS уже задан. GET /items — 200 и JSON-список всех элементов, отсортированный по id. GET /items/<id> — 200 и JSON-объект, а если такого id нет, то 404 и JSON {"error": "not found"}. Везде заголовок Content-Type: application/json.', 'import json
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-rest-post', 1, 'stdout', 'REST: создание ресурса', 'Добавьте в Handler метод do_POST для пути /items. Тело — JSON {"name": ...}. Создайте элемент с новым id (максимальный id + 1), верните 201, заголовок Location: /items/<id> и JSON созданного элемента. Если тело — не JSON или в нём нет непустого name, верните 400 и {"error": "bad request"}. Словарь ITEMS изменяйте на месте.', 'import json
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-paginate', 2, 'stdout', 'Пагинация', 'Напишите функцию paginate(items, page, per_page), страницы нумеруются с 1. Верните словарь: {''items'': элементы страницы, ''page'': page, ''pages'': общее число страниц, ''next'': номер следующей страницы или None}. Если page вне диапазона (меньше 1 или больше pages), items — пустой список, а next — None. Для пустого списка pages = 0.', 'def paginate(items, page, per_page):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-etag', 3, 'stdout', 'ETag и условный GET', 'Напишите make_etag(body: bytes) — строка в кавычках из первых 8 символов sha1-хеша тела (например ''"a94a8fe5"''), и conditional_get(headers: dict, body: bytes) -> (status, response_headers, response_body). Если в headers есть ''If-None-Match'', равный ETag тела, верните (304, {''ETag'': etag}, b''''). Иначе (200, {''ETag'': etag}, body).', 'import hashlib
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-bearer', 4, 'stdout', 'Токен предъявителя: 401 и 403', 'Напишите authorize(headers, tokens, scope), где tokens — словарь {токен: множество_прав}. Заголовок ''Authorization: Bearer <токен>''. Верните (200, ''ok''), если токен известен и scope входит в его права; (401, ''unauthorized''), если заголовка нет, схема не Bearer или токен неизвестен; (403, ''forbidden''), если токен известен, но прав недостаточно.', 'def authorize(headers, tokens, scope):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-bucket', 5, 'stdout', 'Корзина жетонов (rate limit)', 'Напишите класс TokenBucket(rate, capacity): корзина вмещает capacity жетонов и пополняется rate жетонами в секунду (пополнение — дробное), в начале полная. Метод allow(now) принимает время в секундах (неубывающее): сначала пополняет корзину за прошедшее время (но не выше capacity), затем, если жетонов не меньше 1, забирает один и возвращает True, иначе False.', 'class TokenBucket:
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-retry', 6, 'stdout', 'Повторы с учётом Retry-After', 'Напишите get_with_retry(fetch, retries, sleep): fetch() возвращает (status, headers). Повторяйте при статусах 429 и 503 не более retries раз после первой попытки. Пауза перед повтором: если в ответе есть Retry-After (секунды), то это значение, иначе экспоненциальная 1, 2, 4, 8… Вызывайте sleep(пауза). Верните последний статус (успешный или нет).', 'def get_with_retry(fetch, retries, sleep):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-idempotent', 7, 'stdout', 'Идемпотентное создание заказа', 'Напишите класс OrderService с методом create_order(key, payload). Для нового ключа создайте заказ с очередным id (1, 2, …) и верните {''id'': id, ''payload'': payload}. Если тот же ключ приходит повторно (даже с другим payload), верните сохранённый результат первого вызова и не создавайте новый заказ. Атрибут created — число реально созданных заказов.', 'class OrderService:
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-ws-accept', 8, 'stdout', 'WebSocket: ключ подтверждения', 'Напишите ws_accept(key: str) -> str: значение заголовка Sec-WebSocket-Accept. Нужно склеить key и GUID "258EAFA5-E914-47DA-95CA-C5AB0DC85B11", взять sha1 (байты) и закодировать base64 в строку.', 'import base64
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-ws-frame', 9, 'stdout', 'WebSocket: кадры', 'Напишите encode_text(text) — серверный (немаскированный) текстовый кадр: байт 0x81, затем длина (для длины < 126 — один байт; для 126…65535 — байт 126 и 2 байта длины big-endian), затем UTF-8. И decode_frame(data) -> (opcode, payload_bytes) для кадра клиента: если установлен бит маски (второй байт & 0x80), после длины идут 4 байта ключа маски, и каждый байт данных нужно обработать XOR с ключом[i % 4]. Опкод — младшие 4 бита первого байта.', 'import struct
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-sse', 10, 'stdout', 'Server-Sent Events: формат', 'Напишите sse_encode(events) и sse_decode(text). События — список словарей с ключами data (строка, может быть многострочной), необязательными event и id. Кодирование: для каждого события строки ''id: …'', ''event: …'' (если есть), затем для каждой строки data — ''data: …'', и пустая строка в конце. Декодирование — обратно: блоки разделены пустой строкой; многострочные data склеиваются через \n. Верните список словарей только с теми ключами, что были в блоке.', 'def sse_encode(events):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-varint', 11, 'stdout', 'Protobuf: varint', 'Напишите encode_varint(n) -> bytes и decode_varint(data) -> (число, сколько_байт_прочитано). В varint число раскладывается по 7 бит, младшие группы идут первыми, у всех байтов, кроме последнего, старший бит равен 1. Например, 300 → b''\xac\x02''. Добавьте pb_field(field_number, value) -> bytes: ключ поля varint((field_number << 3) | 0), затем varint(value).', 'def encode_varint(n):
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 14, 'net14-grpc-frame', 12, 'stdout', 'gRPC: префикс сообщения', 'Каждое сообщение gRPC идёт с 5-байтовым префиксом: 1 байт флага сжатия (0) и 4 байта длины big-endian. Напишите grpc_frame(payload) -> bytes и grpc_unframe(stream) -> список сообщений из байтового потока, где подряд идёт несколько кадров. Если последний кадр обрезан (данных меньше заявленной длины), он игнорируется.', 'import struct
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 15, 'n15-where', 0, 'lab', 'Где пропал пакет', 'Клиент пингует сервер без проблем, но подключение к порту 8080 молчит — ни отказа, ни ответа. По пути три маршрутизатора. Выполните `traceroute 10.0.4.10` на клиенте, затем `curl 10.0.4.10:8080`, а потом откройте терминалы маршрутизаторов и выполните `tcpdump -i any tcp`. Найдите маршрутизатор, на который SYN приходит, но дальше не уходит, и снимите правило, которое его останавливает.', '', 'На том маршрутизаторе, где SYN входит и не выходит, в секции «Файрвол» удалите правило DROP для tcp/8080. Подсказка: журнал ▶ показывает «файрвол: DROP» и устройство.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 15, 'n15-mtu', 1, 'lab', 'Маленькое проходит, большое — нет', 'Между офисами проложен туннель с MTU 1400, а маршрутизатор R1 блокирует ICMP «frag needed». Клиент шлёт пакеты по 1500 байт с запретом фрагментации, они пропадают, и никто не сообщает об этом отправителю. Определите порог: `ping -c 1 -s 1472 -M do 10.0.2.10` не проходит, `-s 1372` проходит. Выставьте MTU интерфейса клиента, чтобы большие пакеты помещались в туннель (не меньше 1300, чтобы не терять эффективность).', '', '`ip link set eth0 mtu 1400` на клиенте. Размер данных пинга = MTU − 28 байт заголовков: 1400 − 28 = 1372.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 15, 'n15-bind', 2, 'lab', 'Сервис слушает только localhost', 'Веб-сервис на сервере работает: `curl 127.0.0.1` изнутри отвечает. Но клиенты получают отказ на порту 80. Откройте терминал сервера и выполните `ss -ltn`: сервис слушает 127.0.0.1:80, то есть только локальные подключения. Перепривяжите его, чтобы он слушал все адреса.', '', 'На сервере: `listen tcp 80 0.0.0.0` или кнопка «слушать везде» в секции слушающих портов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 15, 'n15-triage', 3, 'lab', 'Три уровня сразу', 'Пользователь пишет: «https://www.example.org не открывается». На пути три независимые поломки: клиент неверно указал DNS-сервер, сервис на 443-м порту слушает не там, где нужно, а сертификат просрочен. Идите по уровням: `dig www.example.org`, потом `curl -v https://www.example.org/`, `ss -ltn` на сервере, `tls show`. Найдите и исправьте все три причины.', '', '1) на клиенте: `echo "nameserver 192.168.0.53" > /etc/resolv.conf`; 2) на сервере: `listen tcp 443 0.0.0.0`; 3) на сервере: `tls cert new www.example.org --issuer PublicIntCA --days 90`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 16, 'n16-portfwd', 0, 'lab', 'Два сервиса за одним адресом', 'Снаружи виден один адрес шлюза 203.0.113.2. За ним два сервера: веб (192.168.0.10, порт 80) и SSH (192.168.0.20, порт 22). Нужно пробросить 8080 → 192.168.0.10:80 и 2222 → 192.168.0.20:22. Политика FORWARD — DROP: помните, что фильтр видит уже внутренние адреса и порты, так что разрешить нужно именно их. Остальное снаружи должно оставаться закрытым.', '', 'DNAT: `iptables -t nat -A PREROUTING -i eth1 -p tcp --dport 8080 -j DNAT --to-destination 192.168.0.10:80` (и 2222 → 192.168.0.20:22). Разрешения: `iptables -A FORWARD -p tcp -d 192.168.0.10 --dport 80 -j ACCEPT` и `iptables -A FORWARD -p tcp -d 192.168.0.20 --dport 22 -j ACCEPT`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 16, 'n16-dmz', 1, 'lab', 'Зоны: LAN, DMZ и интернет', 'Трёхногий файрвол: eth0 — внутренняя сеть LAN, eth1 — демилитаризованная зона с веб-сервером, eth2 — интернет. Политика FORWARD — DROP. Настройте правила: из LAN можно куда угодно; из интернета — только HTTPS (tcp/443) на веб-сервер в DMZ; из DMZ во внутреннюю сеть — ничего; ответы на разрешённые соединения пропускаются.', '', '1) `iptables -A FORWARD -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT`; 2) `iptables -A FORWARD -i eth0 -j ACCEPT` (всё, что идёт из LAN); 3) `iptables -A FORWARD -p tcp -d 203.0.113.2 --dport 443 -j ACCEPT`. Всё остальное, включая DMZ → LAN, остановит политика DROP.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 16, 'n16-hairpin', 2, 'lab', 'Петля через шлюз (hairpin NAT)', 'Проброс 203.0.113.2:8080 → 192.168.0.20:80 работает для гостей из интернета, но внутренний клиент, открывая тот же публичный адрес, получает тишину: сервер отвечает ему напрямую, а клиент ждал ответ от 203.0.113.2 и отбрасывает чужой. Добавьте на шлюзе подмену источника для трафика LAN к серверу через интерфейс eth0.', '', '`iptables -t nat -A POSTROUTING -s 192.168.0.0/24 -d 192.168.0.20 -o eth0 -j MASQUERADE` — тогда сервер увидит источником шлюз и вернёт ответ ему, а шлюз развернёт обратно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 16, 'n16-proxy', 3, 'lab', 'Выход в интернет только через прокси', 'Рабочие станции не должны выходить в интернет напрямую: файрвол пропускает только прокси-сервер 192.168.0.5. Сейчас прокси не может связаться с сайтами (его трафик тоже режется), а политика прокси ничего не запрещает. Разрешите на шлюзе выход прокси-серверу и запретите на прокси сайт social.example. Проверка: `curl -x 192.168.0.5:3128 http://news.example/` должен вернуть 200, а social.example — 403 от прокси.', '', 'На шлюзе: `iptables -A FORWARD -s 192.168.0.5 -j ACCEPT`. На прокси: `proxy deny social.example` или форма «запретить». Прямые запросы с рабочей станции остаются закрытыми.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 17, 'n17-pool', 0, 'lab', 'Добавьте серверы в пул', 'Сервис вырос, поставили ещё два сервера (10.0.1.12 и 10.0.1.13), но балансировщик по-прежнему шлёт всё на первый. Добавьте оба в пул и убедитесь, что девять запросов раскладываются по трём серверам.', '', 'На балансировщике: `lb add 10.0.1.12:80` и `lb add 10.0.1.13:80` либо поле «+ в пул» в карточке. Проверьте командой `lb show`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 17, 'n17-health', 1, 'lab', 'Проверка здоровья', 'В пуле три сервера, но второй не слушает порт 80 — каждый третий запрос получает отказ. Включите проверку здоровья на балансировщике: он перестанет отправлять запросы мёртвому серверу, и все соединения будут успешными.', '', '`lb health on` или флажок «проверка здоровья» в карточке балансировщика. Потом запустите ▶ у цели и посмотрите, на какие серверы попали запросы.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 17, 'n17-sticky', 2, 'lab', 'Привязка клиента к серверу', 'Приложение хранит сессию в памяти сервера: после входа каждый следующий запрос должен попадать на тот же сервер, а сейчас запросы клиента разбросаны по кругу. Переключите алгоритм на привязку по адресу клиента.', '', '`lb algo hash` или выбор «привязка по адресу клиента» в карточке. Помните: это временное решение — лучше выносить сессии во внешнее хранилище.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 17, 'n17-rproxy', 3, 'lab', 'Обратный прокси: маршрутизация по пути', 'Единая точка входа 10.0.0.80 должна разбирать запросы: всё, кроме /api, — на веб-сервер 10.0.2.20:80, а /api — на сервер API 10.0.2.10:8080. Сейчас правил нет, и прокси отвечает «no route». Добавьте два правила, более длинный путь побеждает.', '', '`rproxy add * / 10.0.2.20:80` и `rproxy add * /api 10.0.2.10:8080`. Проверка: `curl http://10.0.0.80/` и `curl http://10.0.0.80/api/items`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 17, 'n17-cdn', 4, 'lab', 'Кэш на узле CDN', 'Узел CDN стоит рядом с клиентом (RTT меньше миллисекунды), а исходный сервер — на другом континенте (около 120 мс). Узел уже передаёт запросы дальше, но ничего не кэширует: каждый ответ приходит издалека. Включите кэш для всех путей и убедитесь: второй запрос отдаётся из кэша заголовком X-Cache: HIT и укладывается в 20 мс.', '', '`rproxy cache / on` на узле или флажок «кэш» у правила. Выполните `curl -I http://cdn.example/logo.png` дважды: первый ответ MISS, второй HIT.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 18, 'n18-keys', 0, 'lab', 'Вход по ключу вместо пароля', 'Сервер пускает пользователя alice по паролю alice123, и ботам этого достаточно. Нужно перейти на ключи. На ПК создайте ключ (`ssh-keygen`), скопируйте его на сервер (`ssh-copy-id -P alice123 alice@192.168.0.20`; пароль нужен один раз), проверьте вход по ключу, а затем выключите парольный вход на сервере (`sshd password off`).', '', 'Порядок важен: сначала ключ и копирование, потом отключение паролей — иначе вы отрежете себе вход. Проверка: `ssh alice@192.168.0.20` входит по ключу, `ssh -o PubkeyAuthentication=no -P alice123 alice@192.168.0.20` — отказ.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 18, 'n18-hostkey', 1, 'lab', 'Ключ хоста изменился', 'После переустановки сервера (администратор подтвердил: смена ключа плановая) вход выдаёт «REMOTE HOST IDENTIFICATION HAS CHANGED». В known_hosts клиента остался старый ключ. Удалите устаревшую запись для 192.168.0.20 (`ssh-keygen -R 192.168.0.20`) и войдите снова — клиент запомнит новый ключ.', '', '`ssh-keygen -R 192.168.0.20`, затем `ssh alice@192.168.0.20`. Не выключайте проверку ключа хоста навсегда: она защищает от подмены сервера.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 18, 'n18-jump', 2, 'lab', 'Бастион: вход во внутреннюю сеть', 'Сервер 10.0.2.20 во внутренней сети доступен по SSH только с бастиона 10.0.1.5 — так настроен файрвол. Напрямую с ПК он недоступен. Настройте вход `ssh -J alice@10.0.1.5 alice@10.0.2.20` (ключ клиента уже создан): разрешите ключ ПК (`ssh-keygen -l` покажет отпечаток) и на бастионе, и на внутреннем сервере для пользователя alice. Парольный вход там выключен.', '', '`ssh-keygen -l` на ПК → отпечаток. На бастионе и на внутреннем сервере: `sshd authorize alice <отпечаток>`. Затем `ssh -J alice@10.0.1.5 alice@10.0.2.20`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 18, 'n18-vpn', 3, 'lab', 'VPN между двумя офисами', 'Офисы А (192.168.1.0/24) и Б (192.168.2.0/24) связаны только через интернет, а интернет не маршрутизирует частные адреса. Постройте туннель между шлюзами: на шлюзе А пир 198.51.100.1, адрес туннеля 10.9.0.1/30; на шлюзе Б пир 203.0.113.1, адрес 10.9.0.2/30; общий секрет у обоих одинаковый. Затем добавьте маршруты в чужие сети через туннель.', '', '`vpn add wg0 --peer 198.51.100.1 --address 10.9.0.1/30 --key s3cr3t` на А и `vpn add wg0 --peer 203.0.113.1 --address 10.9.0.2/30 --key s3cr3t` на Б. Маршруты: на А `ip route add 192.168.2.0/24 dev wg0`, на Б `ip route add 192.168.1.0/24 dev wg0`. Выполните ▶ и найдите в журнале упаковку «туннель wg0».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 18, 'n18-split', 4, 'lab', 'Раздельный туннель', 'Ноутбук сотрудника дома: туннель к корпоративному шлюзу уже поднят, но маршрут по умолчанию ведёт в туннель — весь интернет идёт через офис, да и сам туннель потерял путь к пиру (ping в корпоративную сеть не проходит). Сделайте раздельный туннель: корпоративные сети 10.0.0.0/8 — в туннель (wg0), всё остальное — напрямую через домашний роутер 192.168.100.1.', '', '`ip route del default`, затем `ip route add default via 192.168.100.1` и `ip route add 10.0.0.0/8 dev wg0`. Проверьте: ping 10.0.0.5 идёт через корпоративный шлюз, ping 198.51.100.10 — нет.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 19, 'n19-arp', 0, 'lab', 'Подмена ARP: трафик идёт через чужой ПК', 'В локальной сети появился ПК злоумышленника 192.168.0.66: он рассылает ложные ARP-ответы, и трафик ПК к шлюзу 192.168.0.1 идёт через него. Посмотрите на ПК `arp -n`: у шлюза не его MAC. Узнайте настоящий MAC шлюза (`ip addr` на шлюзе) и закрепите его на ПК статической записью, чтобы ложные ответы перестали действовать.', '', 'На шлюзе: `ip addr` → MAC интерфейса eth0 (28:28:00:00:…). На ПК: `arp -s 192.168.0.1 <этот MAC>`. Проверка: `arp -n` и ▶ у цели — пакеты больше не заходят на ПК злоумышленника.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 19, 'n19-synflood', 1, 'lab', 'SYN-флуд на веб-сервер', 'Злоумышленник заваливает сервер SYN-пакетами, и настоящие клиенты не могут подключиться (запрос клиента молчит; в журнале ▶ — «очередь переполнена»). Включите на сервере SYN-куки: тогда состояние до подтверждения не хранится и очередь не переполняется. Можно ещё закрыть источник файрволом, но куки защищают от любых источников.', '', 'На сервере: `sysctl -w net.ipv4.tcp_syncookies=1`. Альтернатива на файрволе: `iptables -A FORWARD -s 198.51.100.66 -j DROP`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 19, 'n19-scan', 2, 'lab', 'Найдите сканер и закройте лишнее', 'Кто-то обходит порты сервера. Запустите на шлюзе `tcpdump -i any tcp` и найдите источник: десятки SYN на разные порты с одного адреса. Заблокируйте его на файрволе, закройте на сервере ненужный Telnet (порт 23) и убедитесь, что легитимный пользователь по-прежнему работает с SSH и сайтом.', '', 'Источник — 198.51.100.66. На шлюзе: `iptables -A FORWARD -s 198.51.100.66 -j DROP`. На сервере: `close tcp 23`. Порт 3306 (база) должен быть закрыт для всех внешних, он и так не нужен снаружи: закройте его так же `close tcp 3306`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 19, 'n19-exposure', 3, 'lab', 'База данных видна из интернета', 'Во «внутренней» зоне стоят веб (443), сервер приложений и база данных (3306). Политика FORWARD сейчас ACCEPT, поэтому базу видно из интернета. Разрешите порт базы только серверу приложений 203.0.113.20, а всем остальным запретите. Порядок правил важен: сначала разрешение, потом запрет.', '', '`iptables -A FORWARD -p tcp --dport 3306 -s 203.0.113.20 -j ACCEPT`, затем `iptables -A FORWARD -p tcp --dport 3306 -j DROP`. Веб (443) остаётся открытым, так как для него запрета нет.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 20, 'n20-docker', 0, 'lab', 'Docker: выход и публикация порта', 'На Docker-узле 192.168.0.5 работают контейнеры c1 (172.17.0.2, веб на порту 80) и c2 на мосту br0 (172.17.0.0/16). Пересылка между интерфейсами на узле выключена, подмены адресов нет. Сделайте так, чтобы контейнеры выходили во внешнюю сеть (подмена источника на eth0), а клиенту из локальной сети был доступен веб c1 по адресу узла на порту 8080 (проброс 8080 → 172.17.0.2:80). Прямой порт 80 узла остаётся закрытым.', '', 'Три шага на узле: `sysctl -w net.ipv4.ip_forward=1`; `iptables -t nat -A POSTROUTING -s 172.17.0.0/16 -o eth0 -j MASQUERADE`; `iptables -t nat -A PREROUTING -i eth0 -p tcp --dport 8080 -j DNAT --to-destination 172.17.0.2:80`. Именно это Docker делает сам при запуске контейнера с -p 8080:80.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 20, 'n20-natgw', 1, 'lab', 'Приватная подсеть VPC и NAT-шлюз', 'Сервер приложений 10.0.2.10 в приватной подсети должен выходить за обновлениями к репозиторию 198.51.100.10, но оставаться недоступным снаружи. NAT-шлюз (10.0.1.5 в публичной подсети, внешний адрес 203.0.113.9) уже есть. Настройте: маршрут по умолчанию приватной подсети через NAT-шлюз (на маршрутизаторе VPC), подмену источника на шлюзе и обратный маршрут в приватную подсеть на шлюзе.', '', 'На VPC-маршрутизаторе: `ip route add default via 10.0.1.5`. На NAT-шлюзе: `iptables -t nat -A POSTROUTING -o eth1 -j MASQUERADE` и `ip route add 10.0.2.0/24 via 10.0.1.1`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 20, 'n20-sg', 2, 'lab', 'Трёхзвенное приложение: группы безопасности', 'Веб (10.0.1.10), приложение (10.0.2.10) и база (10.0.3.10) в разных подсетях за маршрутизатором VPC. Политика — DROP. Настройте разрешения по принципу минимума: из интернета только HTTPS на веб; веб → приложение на порт 8080; приложение → база на 3306; ответы разрешены. Всё остальное, включая веб → база и интернет → приложение, закрыто.', '', 'Правила FORWARD: 1) ESTABLISHED,RELATED; 2) `-p tcp -d 10.0.1.10 --dport 443`; 3) `-p tcp -s 10.0.1.10 -d 10.0.2.10 --dport 8080`; 4) `-p tcp -s 10.0.2.10 -d 10.0.3.10 --dport 3306`. Политика DROP остановит остальное.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (15, 20, 'n20-k8s', 3, 'lab', 'Service Kubernetes и готовность подов', 'Сервис web (виртуальный адрес 10.96.0.10:80) должен раскладывать запросы по трём подам 10.244.1.5, 10.244.1.6 и 10.244.1.7, но в списке эндпоинтов пока один. К тому же второй под ещё не готов (порт не слушает). Добавьте эндпоинты и включите проверку готовности, чтобы запросы шли только на готовые поды и распределялись между ними.', '', 'На узле (kube-proxy): `lb add 10.244.1.6:80`, `lb add 10.244.1.7:80`, `lb health on` — проба готовности исключит под, который не слушает порт.', '{}');
